-- 006: hero review — angela, argus, arlott. Generated by scripts/review-migration.mjs. Safe to re-run.

alter table hero_profiles
  add column if not exists tier text,
  add column if not exists rank_bias smallint not null default 0,
  add column if not exists strong_vs_types text[] not null default '{}',
  add column if not exists weak_vs_types text[] not null default '{}',
  add column if not exists strong_vs_traits text[] not null default '{}',
  add column if not exists weak_vs_traits text[] not null default '{}',
  add column if not exists good_with_traits text[] not null default '{}';

on conflict (slug) do update set is_meta = excluded.is_meta, ban_recommended = excluded.ban_recommended, ban_note = excluded.ban_note, tags = excluded.tags, power_early = excluded.power_early, power_mid = excluded.power_mid, power_late = excluded.power_late, notes = excluded.notes, status = excluded.status, damage_type = excluded.damage_type, roles = excluded.roles, ratings = excluded.ratings, difficulty = excluded.difficulty, specs_reviewed = excluded.specs_reviewed, tier = excluded.tier, rank_bias = excluded.rank_bias, strong_vs_types = excluded.strong_vs_types, weak_vs_types = excluded.weak_vs_types, strong_vs_traits = excluded.strong_vs_traits, weak_vs_traits = excluded.weak_vs_traits, good_with_traits = excluded.good_with_traits;

on conflict (counter, target) do update set kind = excluded.kind, points = excluded.points, status = excluded.status, why = excluded.why;

on conflict (hero_a, hero_b) do update set points = excluded.points, status = excluded.status, why = excluded.why;

on conflict (trigger, item) do update set for_role = excluded.for_role, status = excluded.status, why = excluded.why;

on conflict (id) do update set weight = excluded.weight, status = excluded.status, description = excluded.description;
