insert into hero_profiles (slug, is_meta, ban_recommended, ban_note, tags, power_early, power_mid, power_late, notes, status, damage_type, roles, ratings, difficulty, specs_reviewed, tier, rank_bias, strong_vs_types, weak_vs_types, strong_vs_traits, weak_vs_traits, good_with_traits) values
  ('argus', false, false, '', array['split', 'thick']::text[], 2, 3, 4, 'Very situational, B tier (A if played right). Good against burst (Kadita, Eudora, Tigreal combos that usually delete a solo target). Stays in long drawn-out teamfights and is a very good split pusher. Generally wins fights against tanks. Weak against kiters that run away (Chang''e, Lesley, Granger, Beatrix); needs the team to back him up, otherwise he split pushes. Team dependent.', 'confirmed', 'physical', array['exp']::text[], '{"frontline":2,"cc":0,"mobility":2,"wave_clear":4,"objective":4,"hg_defense":0,"teamfight":2,"pickoff":2,"sustain":4}'::jsonb, 2, true, 'B', -1, array[]::text[], array[]::text[], array['thick']::text[], array['mobility']::text[], array[]::text[]),
  ('angela', false, false, '', array['enchanter', 'global']::text[], 1, 4, 3, 'C tier — very conditional, usually not good. Works with Alice or Lukas, or high-skill assassins that go in and out with burst: Lancelot, Gusion and Hayabusa are most viable, Yi Sun-shin and Nolan possible. Without tank/sustain heroes she leaves the marksman in a very bad state. Global presence is one of her biggest advantages. Pickoff comes from her ultimate.', 'confirmed', 'magic', array['roam', 'mid']::text[], '{"frontline":0,"cc":2,"mobility":2,"wave_clear":2,"objective":0,"hg_defense":2,"teamfight":1,"pickoff":3,"sustain":5}'::jsonb, 1, true, 'C', 0, array[]::text[], array[]::text[], array[]::text[], array[]::text[], array[]::text[]),
  ('arlott', true, false, '', array['dive', 'pickoff']::text[], 4, 5, 3, 'Very strong — S tier if played correctly. Like Lancelot but stronger, and has crowd control too. Not a frontliner but huge damage; overwhelms enemies and makes a mess. Falls off late. Strong against teams without lockdown. Synergy with crowd-control allies. Can still deal with split pushers if played right. Usually builds lifesteal, so bring anti-heal. Countered by Phoveus (cancels dashes, out-sustains, teleports), Minsitthar and Khufra (dash cancels), Kaja (lockdown).', 'confirmed', 'physical', array['exp']::text[], '{"frontline":2,"cc":3,"mobility":5,"wave_clear":2,"objective":2,"hg_defense":0,"teamfight":3,"pickoff":5,"sustain":2}'::jsonb, 4, true, 'S', -1, array['Split push']::text[], array[]::text[], array[]::text[], array['lockdown']::text[], array['cc']::text[])
